      if (dto.warehouseId || dto.branchId) await this.warehouse(tenantId, dto.warehouseId ?? receipt!.warehouseId, dto.branchId ?? receipt!.branchId);
      const items = dto.items ? await this.prepareReceiptItems(tx, tenantId, dto.items, dto.receivedAt ?? receipt!.receivedAt) : undefined;
