      const updated = await tx.restaurantGoodsReceipt.update({ where: { id }, data: { branchId: dto.branchId, warehouseId: dto.warehouseId, supplierId: dto.supplierId, supplierInvoiceNumber: dto.supplierInvoiceNumber, receivedAt: dto.receivedAt ? new Date(dto.receivedAt) : undefined, notes: dto.notes, ...(items ? { items: { create: items } } : {}) } as any, include: { items: true } });
      await this.recordReceiptHistory(tx, tenantId, updated, 'UPDATED', userId, this.receiptSnapshot(receipt), this.receiptSnapshot(updated));
