  async confirmReceipt(tenantId: string, userId: string, id: string) {
    return this.prisma.$transaction(async (tx) => {
      const receipt = await tx.restaurantGoodsReceipt.findFirst({ where: { id, tenantId }, include: { items: true } });
      if (!receipt) this.bad('Entrada no encontrada');
      if (receipt!.status === RestaurantDocumentStatus.CONFIRMED) return receipt;
      if (receipt!.status !== RestaurantDocumentStatus.DRAFT) this.bad('La entrada ya fue procesada');
      const claim = await tx.restaurantGoodsReceipt.updateMany({ where: { id, tenantId, status: RestaurantDocumentStatus.DRAFT }, data: { status: RestaurantDocumentStatus.CONFIRMED, confirmedBy: userId, confirmedAt: new Date() } });
      if (claim.count !== 1) return tx.restaurantGoodsReceipt.findUnique({ where: { id }, include: { items: true } });
      for (const item of receipt.items) {
        const balance = await tx.restaurantInventoryBalance.findUnique({ where: { tenantId_branchId_warehouseId_ingredientId: { tenantId, branchId: receipt.branchId, warehouseId: receipt.warehouseId, ingredientId: item.ingredientId } } });
        const oldQty = Number(balance?.quantityOnHand ?? 0); const oldCost = Number(balance?.averageCost ?? 0); const qty = Number(item.inventoryQuantity);
        const avg = oldQty + qty === 0 ? 0 : ((oldQty * oldCost) + Number(item.totalCost)) / (oldQty + qty);
        await tx.restaurantInventoryBalance.upsert({ where: { tenantId_branchId_warehouseId_ingredientId: { tenantId, branchId: receipt.branchId, warehouseId: receipt.warehouseId, ingredientId: item.ingredientId } }, update: { quantityOnHand: oldQty + qty, averageCost: avg }, create: { tenantId, branchId: receipt.branchId, warehouseId: receipt.warehouseId, ingredientId: item.ingredientId, quantityOnHand: qty, averageCost: Number(item.totalCost) / qty } });
        const lot = await tx.restaurantInventoryLot.upsert({ where: { tenantId_warehouseId_ingredientId_lotNumber: { tenantId, warehouseId: receipt.warehouseId, ingredientId: item.ingredientId, lotNumber: item.lotNumber ?? receipt.receiptNumber } }, update: { remainingQuantity: { increment: qty }, status: 'ACTIVE' }, create: { tenantId, branchId: receipt.branchId, warehouseId: receipt.warehouseId, ingredientId: item.ingredientId, lotNumber: item.lotNumber ?? receipt.receiptNumber, expirationDate: item.expirationDate, receivedAt: receipt.receivedAt, initialQuantity: qty, remainingQuantity: qty, unitCost: Number(item.totalCost) / qty, sourceReceiptItemId: item.id } });
        await tx.restaurantInventoryMovement.create({ data: { tenantId, branchId: receipt.branchId, warehouseId: receipt.warehouseId, ingredientId: item.ingredientId, movementType: RestaurantMovementType.GOODS_RECEIPT, direction: RestaurantMovementDirection.IN, quantity: qty, unitCost: Number(item.totalCost) / qty, totalCost: item.totalCost, referenceType: 'GOODS_RECEIPT', referenceId: receipt.id, lotId: lot.id, createdBy: userId } });
        await tx.restaurantIngredient.update({ where: { id: item.ingredientId }, data: { currentAverageCost: avg } });
      }
      const confirmed = await tx.restaurantGoodsReceipt.findUnique({ where: { id: receipt.id }, include: { items: true } });
      await this.recordReceiptHistory(tx, tenantId, confirmed, 'CONFIRMED', userId, this.receiptSnapshot(receipt), this.receiptSnapshot(confirmed));
      return confirmed;
    });
  }
  async cancelReceipt(tenantId: string, userId: string, id: string) { return this.reverseDocument(tenantId, userId, id, 'GOODS_RECEIPT', 'restaurantGoodsReceipt'); }
  async receipts(tenantId: string, filters: { branchId?: string; warehouseId?: string; status?: string }) {
    const receipts: any[] = await this.prisma.restaurantGoodsReceipt.findMany({ where: { tenantId, ...(filters.branchId ? { branchId: filters.branchId } : {}), ...(filters.warehouseId ? { warehouseId: filters.warehouseId } : {}), ...(filters.status ? { status: filters.status as any } : {}) }, orderBy: { receivedAt: 'desc' }, include: { items: true } });
    const ingredientIds = [...new Set(receipts.flatMap((receipt) => receipt.items.map((item: any) => item.ingredientId)))];
    const unitIds = [...new Set(receipts.flatMap((receipt) => receipt.items.map((item: any) => item.purchaseUnitId)))];
    const [ingredients, units, suppliers, branches, warehouses] = await Promise.all([
      this.prisma.restaurantIngredient.findMany({ where: { tenantId, id: { in: ingredientIds } }, select: { id: true, name: true } }),
      this.prisma.restaurantInventoryUnit.findMany({ where: { id: { in: unitIds }, OR: [{ tenantId }, { tenantId: null }] }, select: { id: true, name: true } }),
      this.prisma.restaurantInventorySupplier.findMany({ where: { tenantId }, select: { id: true, name: true } }),
      this.prisma.branch.findMany({ where: { tenantId }, select: { id: true, name: true } }),
      this.prisma.restaurantInventoryWarehouse.findMany({ where: { tenantId }, select: { id: true, name: true } }),
    ]);
    const names = (records: Array<{ id: string; name: string }>) => new Map(records.map((record) => [record.id, record.name]));
    const ingredientNames = names(ingredients); const unitNames = names(units); const supplierNames = names(suppliers); const branchNames = names(branches); const warehouseNames = names(warehouses);
    return receipts.map((receipt) => ({
      id: receipt.id, branchId: receipt.branchId, warehouseId: receipt.warehouseId, supplierId: receipt.supplierId, reference: receipt.receiptNumber, supplierName: receipt.supplierId ? supplierNames.get(receipt.supplierId) ?? null : null,
      branchName: branchNames.get(receipt.branchId) ?? null, warehouseName: warehouseNames.get(receipt.warehouseId) ?? null,
      date: receipt.receivedAt.toISOString(), invoice: receipt.supplierInvoiceNumber, notes: receipt.notes, status: receipt.status,
      total: receipt.items.reduce((sum: number, item: any) => sum + Number(item.totalCost), 0),
      lines: receipt.items.map((item: any) => ({ id: item.id, ingredientId: item.ingredientId, ingredientName: ingredientNames.get(item.ingredientId) ?? item.ingredientId, purchaseUnitId: item.purchaseUnitId, quantityPurchased: Number(item.purchaseQuantity), purchaseUnit: unitNames.get(item.purchaseUnitId) ?? item.purchaseUnitId, conversion: Number(item.conversionFactor), quantityReceived: Number(item.inventoryQuantity), unitCost: Number(item.unitCost), total: Number(item.totalCost), lotNumber: item.lotNumber, expirationDate: item.expirationDate?.toISOString?.() ?? item.expirationDate ?? null })),
    }));
  }
