  async expiringReceipts(tenantId: string, filters: { branchId?: string; warehouseId?: string; days?: number } = {}) {
    const days = Math.min(3650, Math.max(1, Number(filters.days) || 30));
    const now = new Date();
    const until = new Date(now.getTime() + days * 24 * 60 * 60 * 1000);
    const rows: any[] = await this.prisma.restaurantGoodsReceipt.findMany({
      where: {
        tenantId,
        status: RestaurantDocumentStatus.CONFIRMED,
        ...(filters.branchId ? { branchId: filters.branchId } : {}),
        ...(filters.warehouseId ? { warehouseId: filters.warehouseId } : {}),
        items: { some: { expirationDate: { not: null, gte: now, lte: until } } },
      },
      orderBy: { receivedAt: 'asc' },
      include: { items: true },
    });
    return (await this.receipts(tenantId, { branchId: filters.branchId, warehouseId: filters.warehouseId, status: RestaurantDocumentStatus.CONFIRMED }))
      .filter((receipt: any) => rows.some((row) => row.id === receipt.id))
      .map((receipt: any) => ({ ...receipt, lines: receipt.lines.filter((line: any) => line.expirationDate && new Date(line.expirationDate) >= now && new Date(line.expirationDate) <= until) }));
  }

  async createRecipe(tenantId: string, userId: string, dto: CreateRecipeDto) {
    const type = dto.type ?? RestaurantRecipeType.MENU_ITEM;
    if (type !== RestaurantRecipeType.MENU_ITEM && !dto.outputIngredientId) this.bad('PREPARATION y YIELD requieren outputIngredientId');
    let cost = 0; const items: any[] = [];
    for (const item of dto.items) { const ingredient = await this.prisma.restaurantIngredient.findFirst({ where: { id: item.ingredientId, tenantId, status: RestaurantInventoryStatus.ACTIVE } }); if (!ingredient) this.bad('Ingrediente no encontrado'); if (Number(ingredient!.currentAverageCost) <= 0) this.bad('El ingrediente no tiene un costo promedio válido'); const converted = await this.convert(item.quantity, item.unitId, ingredient!.inventoryUnitId, tenantId); const itemCost = converted * Number(ingredient!.currentAverageCost) * (1 + (item.wastePercentage ?? 0) / 100); cost += itemCost; items.push({ ...item, convertedInventoryQuantity: converted, calculatedCost: itemCost }); }
    const previous = await this.prisma.restaurantRecipe.findFirst({ where: { tenantId, code: dto.code }, orderBy: { version: 'desc' }, select: { version: true } });
    return this.prisma.$transaction(async (tx) => {
      const recipe: any = await tx.restaurantRecipe.create({ data: { tenantId, createdBy: userId, ...dto, type, version: (previous?.version ?? 0) + 1, requiredStockPolicy: dto.requiredStockPolicy ?? RestaurantStockPolicy.BLOCK, calculatedCost: cost, items: { create: items } } as any, include: { items: true } });
      await tx.restaurantRecipeVersion.create({ data: { tenantId, recipeId: recipe.id, versionNumber: 1, yieldQuantity: dto.yieldQuantity, yieldUnitId: dto.yieldUnitId, sellingPriceSnapshot: dto.sellingPrice, createdBy: userId, changeReason: 'Versión inicial', components: { create: items.map((item: any) => ({ tenantId, componentType: 'INGREDIENT', ingredientId: item.ingredientId, quantity: item.quantity, unitId: item.unitId, convertedGrossQuantity: item.convertedInventoryQuantity, unitCostSnapshot: Number(item.calculatedCost) / Number(item.convertedInventoryQuantity), totalCostSnapshot: item.calculatedCost, wastePercentage: item.wastePercentage })) } } });
      return recipe;
    });
  }
