  async previewConsumption(tenantId: string, dto: CreateConsumptionDto) { const requirements = await this.recipeRequirements(this.prisma, tenantId, dto.items); const balances = await this.prisma.restaurantInventoryBalance.findMany({ where: { tenantId, branchId: dto.branchId, warehouseId: dto.warehouseId, ingredientId: { in: [...requirements.keys()] } } }); const rows = [...requirements.entries()].map(([ingredientId, required]) => { const balance = balances.find((b) => b.ingredientId === ingredientId); const available = Number(balance?.quantityOnHand ?? 0); const unitCost = Number(balance?.averageCost ?? 0); return { ingredientId, requiredQuantity: required.quantity, availableQuantity: available, shortageQuantity: Math.max(0, required.quantity - available), unitCost, requiredCost: required.quantity * unitCost, resultingQuantity: available - required.quantity }; }); return { branchId: dto.branchId, warehouseId: dto.warehouseId, totalCost: rows.reduce((n, r) => n + r.requiredCost, 0), ingredients: rows }; }
  private async recipeRequirements(db: any, tenantId: string, items: Array<{ recipeId: string; quantitySold: number }>) { const result = new Map<string, { quantity: number; cost: number }>(); const lines = await this.consumptionLines(db, tenantId, { items }); for (const line of lines) { const current = result.get(line.ingredientId) ?? { quantity: 0, cost: 0 }; result.set(line.ingredientId, { quantity: current.quantity + line.qty, cost: current.cost }); } return result; }
