  async createWaste(tenantId: string, userId: string, dto: CreateWasteDto) { await this.warehouse(tenantId, dto.warehouseId, dto.branchId); if (dto.reasonId) { const reason = await this.prisma.restaurantWasteReason.findFirst({ where: { id: dto.reasonId, tenantId, status: RestaurantInventoryStatus.ACTIVE } }); if (!reason) this.bad('Motivo de desperdicio no encontrado o inactivo'); } const wasteNumber = await this.number('WST', tenantId, 'restaurantWasteRecord'); const items = await Promise.all(dto.items.map(async (item) => { const ingredient = await this.prisma.restaurantIngredient.findFirst({ where: { id: item.ingredientId, tenantId, status: RestaurantInventoryStatus.ACTIVE } }); if (!ingredient) this.bad('Ingrediente no encontrado o inactivo'); if (item.lotId) { const lot = await this.prisma.restaurantInventoryLot.findFirst({ where: { id: item.lotId, tenantId, branchId: dto.branchId, warehouseId: dto.warehouseId, ingredientId: item.ingredientId, status: 'ACTIVE', remainingQuantity: { gte: item.quantity } } }); if (!lot) this.bad('Lote inválido o insuficiente para desperdicio'); } return { ingredientId: item.ingredientId, quantity: item.quantity, unitId: item.unitId, lotId: item.lotId, notes: item.notes, convertedInventoryQuantity: await this.convert(item.quantity, item.unitId, ingredient!.inventoryUnitId, tenantId), unitCostSnapshot: 0 }; })); return this.prisma.restaurantWasteRecord.create({ data: { tenantId, branchId: dto.branchId, warehouseId: dto.warehouseId, wasteNumber, wasteDate: new Date(dto.wasteDate), reason: dto.reason.trim(), reasonId: dto.reasonId, createdBy: userId, items: { create: items } } } as any); }
